+      transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
+    }
+
+    button:hover {
+      background: linear-gradient(180deg, var(--accent-hover) 0%, #1e40af 100%);
+      box-shadow: 0 14px 28px rgba(37, 99, 235, 0.28);
