+
+    button:focus-visible {
+      outline: 3px solid rgba(37, 99, 235, 0.35);
+      outline-offset: 3px;
+    }
+
+    .status {
+      margin: 0;
+      min-height: 1.4em;
+      color: var(--accent);
+      font-weight: 600;
+    }
+
+    @media (max-width: 520px) {
