+
+      <div class="form-field">
+        <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
+        <input id="email-address" name="emailAddress" type="email" autocomplete="email" required>
+        <div class="error-text" id="email-address-error" hidden></div>
+      </div>
+
+      <div class="form-field">
+        <label for="phone-number">Phone number</label>
+        <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-number-help">
+        <div class="helper-text" id="phone-number-help">Optional. Use a format like +1 555 123 4567 or 555-123-4567.</div>
