<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --panel: #ffffff;
      --text: #122033;
      --muted: #5f6b7a;
      --border: #d9e1ea;
      --border-strong: #9fb0c4;
      --accent: #2563eb;
      --accent-hover: #1d4ed8;
      --error: #b42318;
      --shadow: 0 18px 50px rgba(18, 32, 51, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, #eaf1ff 0%, transparent 42%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      display: grid;
      place-items: center;
      padding: 24px;
    }

    .support-card {
      width: min(100%, 640px);
      background: var(--panel);
      border: 1px solid rgba(159, 176, 196, 0.35);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 32px;
    }

    .eyebrow {
      margin: 0 0 8px;
      font-size: 0.875rem;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
    }

    h1 {
      margin: 0;
      font-size: clamp(1.75rem, 3vw, 2.5rem);
      line-height: 1.1;
    }

    .lead {
      margin: 12px 0 0;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      margin-top: 28px;
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
    }

    .required {
      color: var(--accent);
    }

    input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 14px 16px;
      font: inherit;
      color: var(--text);
      background: #fff;
      transition: border-color 0.2s ease, box-shadow 0.2s ease;
    }

    input::placeholder {
      color: #8a97a6;
    }

    input:focus {
      outline: none;
      border-color: var(--border-strong);
      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
    }

    input[aria-invalid="true"] {
      border-color: var(--error);
      box-shadow: 0 0 0 4px rgba(180, 35, 24, 0.1);
    }

    .helper-text,
    .error-text {
      font-size: 0.92rem;
      line-height: 1.4;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-text {
      color: var(--error);
      min-height: 1.2em;
    }

    .error-text[hidden] {
      display: none;
    }

    button {
      justify-self: start;
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      font: inherit;
      font-weight: 700;
      color: #fff;
      background: linear-gradient(180deg, var(--accent) 0%, #1d4ed8 100%);
      cursor: pointer;
      box-shadow: 0 12px 24px rgba(37, 99, 235, 0.24);
      transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
    }

    button:hover {
      background: linear-gradient(180deg, var(--accent-hover) 0%, #1e40af 100%);
      box-shadow: 0 14px 28px rgba(37, 99, 235, 0.28);
    }

    button:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.35);
      outline-offset: 3px;
    }

    .status {
      margin: 0;
      min-height: 1.4em;
      color: var(--accent);
      font-weight: 600;
    }

    @media (max-width: 520px) {
      .support-card {
        padding: 24px;
        border-radius: 20px;
      }

      button {
        width: 100%;
        justify-self: stretch;
      }
    }
  </style>
</head>
<body>
  <main class="support-card">
    <p class="eyebrow">Support</p>
    <h1>Contact our team</h1>
    <p class="lead">Send us your details and we&apos;ll get back to you as soon as possible.</p>

    <form id="contact-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
        <input id="full-name" name="fullName" type="text" autocomplete="name" required>
        <div class="error-text" id="full-name-error" hidden></div>
      </div>

      <div class="form-field">
        <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
        <input id="email-address" name="emailAddress" type="email" autocomplete="email" required>
        <div class="error-text" id="email-address-error" hidden></div>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-number-help">
        <div class="helper-text" id="phone-number-help">Optional. Use a format like +1 555 123 4567 or 555-123-4567.</div>
        <div class="error-text" id="phone-number-error" hidden></div>
      </div>

      <p class="status" id="form-status" aria-live="polite"></p>
      <button type="submit">Submit</button>
    </form>
  </main>

  <script>
    const form = document.getElementById('contact-form');
    const status = document.getElementById('form-status');

    const fields = [
      {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        message: 'Please enter your full name.'
      },
      {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        message: 'Please enter a valid email address.'
      },
      {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        message: 'Please enter a valid phone number.'
      }
    ];

    function showError(field, message) {
      field.input.setAttribute('aria-invalid', 'true');
      field.error.textContent = message;
      field.error.hidden = false;
    }

    function clearError(field) {
      field.input.removeAttribute('aria-invalid');
      field.error.textContent = '';
      field.error.hidden = true;
    }

    function isValidPhone(value) {
      if (!value.trim()) {
        return true;
      }

      return /^[+]?[\d\s().-]{7,}$/.test(value.trim());
    }

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.textContent = '';

      let hasError = false;

      fields.forEach((field) => clearError(field));

      if (!fields[0].input.value.trim()) {
        showError(fields[0], fields[0].message);
        hasError = true;
      }

      if (!fields[1].input.value.trim() || !fields[1].input.validity.valid) {
        showError(fields[1], fields[1].message);
        hasError = true;
      }

      if (!isValidPhone(fields[2].input.value)) {
        showError(fields[2], fields[2].message);
        hasError = true;
      }

      if (hasError) {
        return;
      }

      status.textContent = 'Thanks — your message has been received.';
      form.reset();
    });
  </script>
</body>
</html>
